			}
		}
		return MergeIndexContent(basePlain, localPlain, remotePlain)
	}
	return nil, false
}

func isLogFile(path string) bool {
	clean := filepath.ToSlash(filepath.Clean(path))
	return clean == "log.md" || strings.HasSuffix(clean, "/log.md")
}
